escenas.animacion:
A.bg('#0b1630','#050a18');
const W=A.W, acc=A.accent;
const kk=(w,d)=>{const v=A.k(w,d);return (typeof v==='number'&&isFinite(v))?v:d;};
const tE=kk('estación',0.667), tC=kk('concurrida',1.333), tM=kk('mundo',2.0), tT=kk('Tokio',2.667);
const tTr=kk('tres',4.0), tPe=kk('personas',5.0), tCa=kk('casi',6.333), tN=kk('nadie',6.667);
const lanes=7, laneY=i=>520+i*88, L=1260, gap=210, gateX=540;
const rnd=A.rand(7);
const vs=[],ph=[];
for(let i=0;i<lanes;i++){vs.push(235+rnd()*55);ph.push(rnd()*L);}
const v3=260; vs[3]=v3;
const tHit=tN+0.33;
ph[3]=(((gateX+100)-tHit*v3)%L+L)%L;
const dens=A.p(tC-0.3,1.6,'softInOut');
const nShow=1+dens*5;
const gA=A.p(0.15,0.6,'softLand');
const hp=A.p(tCa,0.5,'snapSettle');
let shake=0;
if(t>tTr+1.1) shake=8*(1-A.p(tTr+1.1,0.45,'cruise'));
const cam=A.lerp(1.12,1,A.p(0,2.6,'glide'));
const xOf=(i,j)=>((j*gap+ph[i]+t*vs[i])%L+L)%L-100;

A.with(()=>{
  // muros de la estación
  const pw=A.p(0,0.9,'softInOut');
  A.line([[40,462],[1040,462]],{stroke:A.pal.paleBlue,lw:5,progress:pw});
  A.line([[1040,1104],[40,1104]],{stroke:A.pal.paleBlue,lw:5,progress:pw});
  // líneas guía de carriles
  for(let i=0;i<lanes;i++){
    A.line([[60,laneY(i)],[1020,laneY(i)]],{stroke:A.pal.paleBlue,lw:2,alpha:0.12*pw,dash:[10,18]});
  }
  // personas
  const near=new Array(lanes).fill(0);
  for(let i=0;i<lanes;i++){
    const y=laneY(i);
    for(let j=0;j<6;j++){
      let a=A.clamp(nShow-j)*gA;
      if(a<=0) continue;
      const x=xOf(i,j);
      const isHero=(i===3&&j===0);
      if(!isHero) a*=(1-0.6*hp);
      near[i]=Math.max(near[i],A.clamp(1-Math.abs(x-gateX)/70)*a);
      A.line([[x-90,y],[x-24,y]],{stroke:acc,lw:6,alpha:0.25*a});
      A.rect(x-13,y-22,26,44,{r:13,fill:isHero?acc:'#9fc0ea',alpha:a});
      A.circle(x,y,12,{fill:'#ffffff',alpha:a});
    }
  }
  // torniquetes
  for(let g=0;g<=lanes;g++){
    const y=laneY(g)-44;
    const s=A.pop(0.3+g*0.07,0.45);
    if(s<=0) continue;
    const lit=Math.max(g>0?near[g-1]:0,g<lanes?near[g]:0);
    A.with(()=>{
      const pts=[[gateX-22,y-16],[gateX+22,y-16],[gateX+22,y+16],[gateX-22,y+16]];
      A.rect(gateX-22,y-16,44,32,{r:6,fill:'#14284d',stroke:A.pal.paleBlue,lw:3});
      A.lib.hatch(ctx,pts,{angle:45,spacing:8,width:1.2,color:'rgba(170,200,255,0.35)'});
      A.circle(gateX,y,7,{fill:lit>0.05?acc:'#2a3f66',glow:lit*30,alpha:0.4+0.6*Math.max(lit,0.2)});
    },{x:gateX,y:y,scale:s});
  }
  // héroe: no se detiene
  if(hp>0){
    const x=xOf(3,0), y=laneY(3);
    A.circle(x,y,44,{stroke:acc,lw:5,alpha:hp});
    A.rings(x,y,tHit,{count:2,speed:260,gap:0.25,maxR:120,color:acc,lw:3,alpha:0.7});
    const ls=A.pop(tN,0.45);
    if(ls>0) A.label('SIN FRENAR',x,y-92,{size:44,bg:acc,color:'#0b1630',scale:ls});
  }
},{x:540,y:780,scale:cam,shake:shake});

// zona secundaria: ranking -> Tokio -> contador
const pM=A.pop(tM,0.45), outM=A.p(tT,0.3,'accelExit');
if(pM>0&&outM<1) A.label('#1 DEL MUNDO',540,1410,{size:46,bg:'#1d3566',color:'#ffffff',scale:pM*(1-outM)});
const pT=A.pop(tT,0.45);
if(pT>0) A.label('TOKIO · SHINJUKU',540,1410,{size:46,bg:'#1d3566',color:'#ffffff',scale:pT});
const cp=A.p(tTr,1.1,'expo.out');
if(t>=tTr){
  const val=Math.round(A.lerp(0,3000000,cp)).toString().replace(/\B(?=(\d{3})+(?!\d))/g,'.');
  const cs=A.pop(tTr,0.4);
  A.with(()=>{
    A.text(val,540,1575,{size:150,color:acc,weight:'900',align:'center',stroke:'#050a18',strokeWidth:8});
  },{x:540,y:1530,scale:cs});
  A.rings(540,1530,tTr+1.1,{count:3,speed:500,gap:0.12,maxR:380,color:acc,lw:4,alpha:0.5});
}
const pp=A.p(tPe,0.5,'softLand');
if(pp>0) A.text('personas al día',540,1670+(1-pp)*30,{size:48,color:'#ffffff',weight:'700',align:'center',alpha:pp});
if(t>tTr+1.05) A.flash(tTr+1.1,0.25,0.18);

const W=A.W,H=A.H;A.bg('#06121f','#0a2626');
const acc=A.accent, dark='#06121f';
const tT=A.k('tarjeta:',1.333), tS=A.k('Suica.',2.0), tN=A.k('nombre',2.667), tSS=A.k("'suisui',",3.667), tJ=A.k('japonés',4.667), tF=A.k("'fluido,",5.667), tTr=A.k('sin',6.0);
const cx=540, cy=720;
const T=(s,x,y,size,color,weight,alpha,align)=>{if(alpha<=0)return;ctx.save();ctx.globalAlpha*=alpha;ctx.font=(weight||900)+' '+size+'px '+A.FONT;ctx.textAlign=align||'center';ctx.textBaseline='middle';ctx.fillStyle=color;ctx.fillText(s,x,y);ctx.restore();};
// Giro: ? -> tarjeta
const flip=A.p(tT,0.5,'softInOut');
const qsx=flip<0.5?1-flip*2:0;
const csx=flip<0.5?0:(flip-0.5)*2;
// Fase 0: interrogante
if(qsx>0.01){
  const pul=(1+0.05*Math.sin(t*5))*(0.6+0.4*A.p(0,0.5,'snapSettle'));
  A.rings(cx,cy,0.2,{count:3,speed:180,gap:0.6,maxR:320,color:acc,lw:3,alpha:0.4*qsx});
  ctx.save();ctx.translate(cx,cy);ctx.scale(qsx*pul,pul);
  A.circle(0,0,150,{stroke:acc,lw:6,glow:20});
  T('?',0,8,220,'#ffffff',900,1);
  ctx.restore();
}
// Corrientes de flujo (detrás de la tarjeta)
const fp=A.p(tF,0.6,'softInOut');
if(fp>0){
  for(let i=0;i<10;i++){
    const by=440+i*68, ph=i*0.7, amp=14+(i%3)*7;
    const yy=x=>by+Math.sin(x*0.008+ph-t*3)*amp;
    const pts=[];for(let x=-40;x<=1120;x+=40)pts.push([x,yy(x)]);
    A.line(pts,{stroke:acc,lw:3,alpha:0.16*fp});
    for(let j=0;j<3;j++){
      const sx=(((t-tF)*620+j*380+i*97)%1240+1240)%1240-60;
      ctx.save();ctx.globalAlpha=0.8*fp;ctx.strokeStyle=acc;ctx.lineWidth=5;ctx.lineCap='round';
      ctx.beginPath();ctx.moveTo(sx-70,yy(sx-70));ctx.lineTo(sx,yy(sx));ctx.stroke();ctx.restore();
    }
  }
}
// Tarjeta
let tx0=cx-150, ty0=cy+10;
if(csx>0){
  const pop=t<tT+0.25?1:A.pop(tT+0.25,0.45);
  const drift=A.p(tF,0.9,'glide');
  const bob=Math.sin(t*2.2)*6;
  const px=cx+drift*Math.sin((t-tF)*2.4)*40, py=cy+bob;
  const rot=-0.06+Math.sin(t*1.7)*0.015+drift*0.05*Math.sin(t*3);
  const sc=0.85+0.15*pop;
  tx0=px-150; ty0=py+10;
  ctx.save();ctx.translate(px,py);ctx.rotate(rot);ctx.scale(csx*sc,sc);
  const gl=A.p(tS,0.4,'softInOut');
  A.rect(-280,-175,560,350,{r:36,fill:acc,glow:20+30*gl});
  A.lib.hatch(ctx,[[-280,70],[280,30],[280,150],[255,175],[-255,175],[-280,150]],{angle:-0.6,spacing:14,width:2,color:'rgba(6,18,31,0.3)'});
  for(let r=0;r<4;r++)A.rect(110+r*16,-130+r*16,140-r*32,200-r*32,{r:14,stroke:dark,lw:3,alpha:0.35+0.45*gl});
  A.rect(155,-55,50,50,{r:8,fill:dark,alpha:0.65});
  // nombre
  if(t>=tS){
    const s2=A.pop(tS,0.45);
    ctx.save();ctx.translate(-130,10);ctx.scale(s2,s2);
    T('Suica',-105,0,130,dark,900,1,'left');
    ctx.restore();
    const up=A.p(tN,0.5,'glide');
    if(up>0){
      ctx.save();ctx.font='900 130px '+A.FONT;const ws=ctx.measureText('Sui').width;ctx.restore();
      A.line([[-235,80],[-235+ws*up,80]],{stroke:dark,lw:10});
    }
  }
  ctx.restore();
  if(t>=tS){A.rings(px,py,tS,{count:2,speed:520,gap:0.18,maxR:420,color:acc,lw:4,alpha:0.45});}
}
if(t>=tS)A.flash(tS,0.25,0.25);
// SUI SUI sale de la tarjeta
[[380,tSS],[700,tSS+0.17]].forEach(([x,st],k)=>{
  const m=A.p(st,0.55,'whip');
  if(m<=0)return;
  const wave=fp*Math.sin(t*5+k*1.4)*12;
  const X=A.lerp(tx0,x,m), Y=A.lerp(ty0,1015,m)+wave;
  const sz=A.lerp(70,120,m);
  const s=m>=1?A.pop(st+0.55,0.35)*0.1+0.9:1;
  ctx.save();ctx.translate(X,Y);ctx.scale(s,s);
  T('SUI',0,0,sz,k?acc:'#ffffff',900,A.clamp(m*3));
  ctx.restore();
});
// en japonés
const ja=A.p(tJ,0.4,'softLand');
if(ja>0)T('en japonés',540,1420+(1-ja)*20,44,'#C8D0DC',700,ja);
// FLUIDO
if(t>=tF){
  A.label('FLUIDO',540,1560,{size:64,bg:acc,color:dark,scale:A.pop(tF,0.45)});
  A.rings(540,1560,tF,{count:2,speed:420,gap:0.25,maxR:260,color:acc,lw:4,alpha:0.5});
}
const sa2=A.p(tTr+0.1,0.4,'softLand');
if(sa2>0){ctx.save();ctx.translate(540,1660);const s3=A.lerp(0.8,1,sa2);ctx.scale(s3,s3);T('SIN TRABAS',0,0,54,'#ffffff',800,sa2);ctx.restore();}

const ctx2 = ctx; const acc = A.accent; const RED = '#FF5A6E';
A.bg('#0B1A2E', '#050D18');
const tBip = A.k('bip!,', 0.67), tNo = A.k('no', 1.0), tTie = A.k('tiene', 1.33), tBat = A.k('batería:', 1.67);
const tLec = A.k('lector', 2.33), tCampo = A.k('campo', 3.33), tMag = A.k('magnético', 3.67);
const tEnc = A.k('enciende', 4.67), tAce = A.k('acercas.', 5.67);
const cx = 540;
// ---- card motion
const app = A.p(tMag + 0.1, 0.8, 'glide');
const tap = A.p(tAce - 0.15, 0.5, 'softInOut');
let cy = A.lerp(620, 745, app) + (1 - app) * Math.sin(t * 2.2) * 8 + Math.sin(tap * Math.PI) * 14;
const sIn = A.pop(0.05, 0.5);
const xr = A.p(tNo, 0.5, 'softInOut');
const on = A.p(tEnc, 0.35, 'crashIn');
const shake = (t > tBat && t < tBat + 0.3) ? 12 : 0;
// ---- reader
const rp = A.p(tLec, 0.6, 'snapSettle');
const ry = A.lerp(1200, 955, rp);
// ---- field lines (behind)
const fp = A.p(tCampo, 0.6, 'softLand');
if (fp > 0 && rp > 0) {
  for (let i = 0; i < 5; i++) {
    const g = A.p(tCampo + i * 0.08, 0.6, 'softLand');
    const rx = (110 + i * 75) * g, rY = (70 + i * 70) * g;
    const pulse = 0.75 + 0.25 * Math.sin(t * 6 - i);
    ctx.save();
    ctx.globalAlpha = g * (0.75 - i * 0.11) * pulse * (1 + on * 0.3);
    ctx.strokeStyle = acc; ctx.lineWidth = 5;
    ctx.shadowColor = acc; ctx.shadowBlur = 14;
    ctx.setLineDash([22, 16]); ctx.lineDashOffset = -t * 90;
    ctx.beginPath(); ctx.ellipse(cx, ry, Math.max(1, rx), Math.max(1, rY), 0, Math.PI, 2 * Math.PI); ctx.stroke();
    ctx.restore();
  }
  A.rings(cx, ry, tCampo, { count: 3, speed: 420, gap: 0.35, maxR: 520, color: acc, lw: 4, alpha: 0.5 });
}
// ---- reader body
if (rp > 0) {
  A.rect(270, ry, 540, 130, { r: 26, fill: '#13263D', stroke: '#EAF6FF', lw: 4, alpha: rp });
  A.rect(300, ry + 14, 480, 12, { r: 6, fill: acc, alpha: rp * (0.5 + 0.5 * fp), glow: 20 * fp });
  A.text('LECTOR', cx, ry + 85, { size: 44, color: '#EAF6FF', weight: 800, align: 'center', alpha: rp });
}
// ---- card
const W0 = 480, H0 = 300;
function perim(x, y, w, h, u) {
  const P = 2 * (w + h); let d = u * P;
  if (d < w) return [x + d, y]; d -= w;
  if (d < h) return [x + w, y + d]; d -= h;
  if (d < w) return [x + w - d, y + h]; d -= w;
  return [x, y + h - d];
}
A.with(() => {
  const x0 = cx - W0 / 2, y0 = cy - H0 / 2;
  A.rect(x0, y0, W0, H0, { r: 28, fill: '#102A45', stroke: '#EAF6FF', lw: 5, glow: on * 30 });
  // coil
  for (let j = 0; j < 3; j++) {
    const ins = 30 + j * 22;
    A.rect(x0 + ins, y0 + ins, W0 - 2 * ins, H0 - 2 * ins, { r: 18, stroke: on > 0.05 ? acc : '#7FA3C0', lw: 6, alpha: xr * (0.55 + 0.45 * on), glow: on * 28 });
    if (on > 0) {
      for (let n = 0; n < 6; n++) {
        const u = (t * 0.4 + n / 6 + j * 0.11) % 1;
        const pt = perim(x0 + ins, y0 + ins, W0 - 2 * ins, H0 - 2 * ins, u);
        A.circle(pt[0], pt[1], 7, { fill: '#FFFFFF', alpha: on, glow: 18 });
      }
    }
  }
  // chip
  if (on > 0) A.circle(cx, cy, 70 + 10 * Math.sin(t * 10), { fill: acc, alpha: 0.28 * on, glow: 50 });
  A.rect(cx - 50, cy - 38, 100, 76, { r: 12, fill: on > 0.05 ? '#E8FBFF' : '#9FB6C8', stroke: on > 0.05 ? acc : '#EAF6FF', lw: 4, alpha: xr, glow: on * 30 });
  A.line([[cx - 50, cy], [cx + 50, cy]], { stroke: '#102A45', lw: 3, alpha: xr });
  A.line([[cx, cy - 38], [cx, cy + 38]], { stroke: '#102A45', lw: 3, alpha: xr });
  const lb = A.p(tNo + 0.35, 0.5, 'softLand') * (1 - A.p(tTie, 0.3, 'softInOut') * 0.0);
  A.text('ANTENA', x0 + W0 - 40, y0 - 18, { size: 30, color: acc, weight: 800, align: 'right', alpha: lb });
  A.text('CHIP', cx, cy + 74, { size: 28, color: '#EAF6FF', weight: 800, align: 'center', alpha: lb * (1 - on) });
  // opaque front face fades into x-ray
  A.rect(x0, y0, W0, H0, { r: 28, fill: '#2A6FB0', alpha: 1 - xr });
  A.text('bip!', cx, cy + 38, { size: 120, color: '#FFFFFF', weight: 900, align: 'center', alpha: 1 - xr });
  // battery
  const bp = A.pop(tTie, 0.4) * (1 - A.p(tBat + 0.45, 0.4, 'crashOut'));
  if (bp > 0.01) {
    A.with(() => {
      A.rect(cx - 95, cy - 50, 180, 100, { r: 14, fill: '#0B1A2E', stroke: '#FFFFFF', lw: 7 });
      A.rect(cx + 85, cy - 20, 18, 40, { r: 4, fill: '#FFFFFF' });
      A.rect(cx - 78, cy - 33, 60, 66, { r: 6, fill: '#FFFFFF', alpha: 0.85 });
      const cp = A.p(tBat, 0.25, 'crashIn');
      A.line([[cx - 130, cy - 85], [cx + 130, cy + 85]], { stroke: RED, lw: 16, progress: cp });
      A.line([[cx + 130, cy - 85], [cx - 130, cy + 85]], { stroke: RED, lw: 16, progress: A.p(tBat + 0.08, 0.25, 'crashIn') });
    }, { x: cx, y: cy, scale: bp });
  }
}, { x: cx, y: cy, scale: sIn, shake });
if (on > 0) A.rings(cx, cy, tEnc, { count: 2, speed: 600, gap: 0.2, maxR: 420, color: '#FFFFFF', lw: 5, alpha: 0.6 });
A.flash(tEnc, 0.3, 0.35);
// ---- secondary zone labels
const LY = 1470;
function lab(str, a, b, bg, col) {
  if (t < a || t >= b) return;
  const out = A.p(b - 0.2, 0.2, 'accelExit');
  A.label(str, cx, LY, { size: 72, bg: bg, color: col, scale: A.pop(a, 0.45) * (1 - out) });
}
lab('TARJETA bip!', tBip, tTie, '#2A6FB0', '#FFFFFF');
lab('0 BATERÍAS', tBat, tLec + 0.3, RED, '#FFFFFF');
lab('CAMPO MAGNÉTICO', tCampo, tEnc, acc, '#0B1A2E');
lab('¡ENCENDIDA!', tEnc, 99, '#FFFFFF', '#0B1A2E');
if (t >= tLec + 0.3 && t < tCampo) {
  A.text('emite energía...', cx, LY + 20, { size: 54, color: '#EAF6FF', weight: 700, align: 'center', alpha: A.p(tLec + 0.3, 0.4, 'softLand') });
}
if (on > 0) {
  const ap = A.p(tEnc + 0.2, 0.5, 'softLand');
  A.arrow(cx, ry - 10, cx, cy + 165, { progress: ap, color: acc, lw: 8, head: 22, alpha: 0.9 });
}

const ac = A.accent;
A.bg('#120a24', '#06030f', true);
const kTec = A.k('tecnología', 0.667), kS = A.k('Sony', 1.333), kF = A.k('FeliCa,', 2.0);
const kD = A.k('diseñada', 2.333), kP = A.k('principio', 3.333), kSer = A.k('ser', 4.0), kR = A.k('rapidísima.', 4.333);
const W = 620, H = 390, cy = 760;
// card movement
const pIn = A.p(0, 0.7, 'snapSettle');
const pEx = A.p(kSer, 0.55, 'whip');
const X = 540 + A.lerp(-1000, 0, pIn) + A.lerp(0, 150, pEx);
const rot = A.lerp(-0.25, 0, pIn) + Math.sin(t * 1.3) * 0.012;
const Y = cy + Math.sin(t * 1.7) * 6;
const shake = t > kR && t < kR + 0.35 ? 10 * (1 - (t - kR) / 0.35) : 0;

// speed lines behind (rapidísima)
const pSpd = A.p(kSer - 0.1, 0.3, 'softInOut');
if (pSpd > 0) {
  A.particles(22, 7, (i, rnd) => {
    const yy = 560 + rnd() * 420;
    const len = 120 + rnd() * 260;
    const sp = 1800 + rnd() * 1400;
    const xx = 1200 - ((t * sp + rnd() * 1400) % 1500);
    A.line([[xx, yy], [xx + len, yy]], { stroke: i % 3 === 0 ? ac : '#ffffff', lw: 3 + rnd() * 4, alpha: 0.6 * pSpd });
  });
}

A.with(() => {
  A.with(() => {
    // card body
    A.rect(X - W / 2 + 14, Y - H / 2 + 18, W, H, { r: 34, fill: '#000000', alpha: 0.35 });
    A.rect(X - W / 2, Y - H / 2, W, H, { r: 34, fill: '#1c1236', stroke: ac, lw: 5, glow: 18 });
    // hatch shade bottom part
    const hp = [[X - W / 2 + 20, Y + 60], [X + W / 2 - 20, Y + 60], [X + W / 2 - 20, Y + H / 2 - 20], [X - W / 2 + 20, Y + H / 2 - 20]];
    if (A.lib && A.lib.hatch) A.lib.hatch(ctx, hp, { angle: -0.7, spacing: 16, width: 1.5, color: 'rgba(179,136,255,0.25)' });
    // coil antenna
    for (let i = 0; i < 3; i++) {
      const ins = 36 + i * 24;
      const x0 = X - W / 2 + ins, x1 = X + W / 2 - ins, y0 = Y - H / 2 + ins, y1 = Y + H / 2 - ins;
      A.line([[x0, y0], [x1, y0], [x1, y1], [x0, y1], [x0, y0 + 6]], {
        stroke: i === 1 ? '#ffffff' : ac, lw: 5, alpha: 0.9,
        progress: A.p(kTec - 0.2 + i * 0.15, 0.8, 'glide')
      });
    }
    // chip
    const cs = A.pop(kS, 0.45);
    if (cs > 0.01) {
      A.with(() => {
        A.rect(X - 75, Y - 60, 150, 120, { r: 16, fill: '#d9c6ff', stroke: '#ffffff', lw: 4, glow: 25 });
        for (let j = 0; j < 4; j++) {
          A.line([[X - 75, Y - 36 + j * 24], [X - 100, Y - 36 + j * 24]], { stroke: '#ffffff', lw: 4 });
          A.line([[X + 75, Y - 36 + j * 24], [X + 100, Y - 36 + j * 24]], { stroke: '#ffffff', lw: 4 });
        }
        A.text('SONY', X, Y + 12, { size: 38, color: '#1c1236', weight: 900, align: 'center' });
      }, { x: X, y: Y, scale: cs });
    }
  }, { x: X, y: Y, rot });

  // rings from chip at FeliCa and pulses after
  if (t > kF) {
    A.rings(X, Y, kF, { count: 3, speed: 520, gap: 90, maxR: 420, color: ac, lw: 5, alpha: 0.8 });
